changeSet.sql:
DO $migration$
DECLARE
    old_is_partitioned BOOLEAN;
    old_exists BOOLEAN;
    legacy_exists BOOLEAN;
    sequence_name TEXT;
BEGIN
    SELECT to_regclass('public.outbox') IS NOT NULL INTO old_exists;

    SELECT to_regclass('public.outbox_legacy') IS NOT NULL INTO legacy_exists;

    IF old_exists THEN
        SELECT EXISTS (
            SELECT 1
            FROM pg_partitioned_table pt
            JOIN pg_class c ON c.oid = pt.partrelid
            JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'public' AND c.relname = 'outbox'
        ) INTO old_is_partitioned;

        IF NOT old_is_partitioned THEN
            IF legacy_exists THEN
                RAISE EXCEPTION 'legacy outbox table already exists while public.outbox is not partitioned';
            END IF;
            ALTER TABLE public.outbox RENAME TO outbox_legacy;
            legacy_exists := TRUE;
        END IF;
    END IF;

    IF to_regclass('public.outbox') IS NULL THEN
        CREATE TABLE public.outbox (
            id            BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
            event_id      UUID NOT NULL,
            event_type    VARCHAR(32) NOT NULL,
            aggregate_id  BIGINT NOT NULL,
            user_id       BIGINT NOT NULL,
            payload       JSONB NOT NULL,
            created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
            processed_at  TIMESTAMP WITH TIME ZONE,
            rejected_at   TIMESTAMP WITH TIME ZONE,
            attempt_count INT NOT NULL DEFAULT 0,
            next_attempt_at TIMESTAMP WITH TIME ZONE,
            lease_owner VARCHAR(128),
            lease_until TIMESTAMP WITH TIME ZONE,
            last_attempt_at TIMESTAMP WITH TIME ZONE,
            last_error TEXT,
            status        VARCHAR(16) NOT NULL DEFAULT 'NEW',
            CONSTRAINT pk_outbox_partitioned PRIMARY KEY (id, created_at),
            CONSTRAINT uq_outbox_event_id_partitioned UNIQUE (event_id, created_at),
            CONSTRAINT ck_outbox_status_partitioned CHECK (status IN ('NEW','PROCESSING','COMPLETED','REJECTED'))
        ) PARTITION BY RANGE (created_at);

        CREATE TABLE public.outbox_default PARTITION OF public.outbox DEFAULT;

        CREATE INDEX idx_outbox_new ON public.outbox (id) WHERE status = 'NEW';
        CREATE INDEX idx_outbox_user_new ON public.outbox (user_id, id) WHERE status = 'NEW';
        CREATE INDEX idx_outbox_status_created ON public.outbox (status, created_at);
    END IF;

    IF legacy_exists AND NOT old_is_partitioned THEN
        INSERT INTO public.outbox
            (id, event_id, event_type, aggregate_id, user_id, payload, created_at,
             processed_at, rejected_at, attempt_count, status, lease_owner, lease_until, next_attempt_at, last_attempt_at, last_error)
        SELECT id, event_id, event_type, aggregate_id, user_id, payload, created_at,
               processed_at, NULL, attempt_count,
               CASE WHEN processed_at IS NULL THEN 'NEW' ELSE 'COMPLETED' END,
               NULL, NULL, NULL, NULL, NULL
        FROM public.outbox_legacy;

        sequence_name := pg_get_serial_sequence('public.outbox', 'id');
        IF sequence_name IS NOT NULL THEN
            PERFORM setval(sequence_name, COALESCE((SELECT MAX(id) FROM public.outbox), 1),
                           (SELECT COUNT(*) > 0 FROM public.outbox));
        END IF;
    END IF;
END $migration$;
